task find_length(s: seq, n: int) returns (r: int)
  requires n >= 0
  requires n <= len(s)
  ensures r >= 0
  ensures r == max(0, max_ones - max_zeros)
  ensures r == max(0, max_zeros - max_ones)
{
  var max_ones: int := 0;
  var max_zeros: int := 0;
  var current_ones: int := 0;
  var current_zeros: int := 0;
  var max_diff: int := 0;
  var min_diff: int := 0;

  current_ones := 0;
  current_zeros := 0;
  min_diff := 0;
  max_diff := 0;

  var i: int := 0;
  while i < n
    invariant 0 <= i and i <= n
    invariant current_ones == count_ones(s, 0, i)
    invariant current_zeros == count_zeros(s, 0, i)
    invariant max_diff >= 0
    invariant min_diff <= 0
    decreases n - i
  {
    if s[i] == 1 {
      current_ones := current_ones + 1;
    } else {
      current_zeros := current_zeros + 1;
    }
    var diff_ones: int := current_ones - current_zeros;
    var diff_zeros: int := current_zeros - current_ones;
    if diff_ones > max_diff {
      max_diff := diff_ones;
    }
    if diff_zeros > min_diff {
      min_diff := diff_zeros;
    }
    i := i + 1;
  }

  r := max(max_diff, -min_diff);
}
